const base = document.createElement('canvas');
const view = document.getElementById('view');
const vctx = view.getContext('2d');
const statusEl = document.getElementById('status');
const hint = document.getElementById('hint');
const ids = ['save','undo','crop','rotate','midArrow','midText'];
let loaded = false, mode = 'crop', sel = null, drag = null, undoStack = [], fileName = 'photo';

function say(msg, err) { statusEl.textContent = msg; statusEl.className = err ? 'error' : ''; }
function el(id) { return document.getElementById(id); }
function refreshButtons() {
  for (const id of ids) el(id).disabled = !loaded;
  el('undo').disabled = !loaded || undoStack.length === 0;
  el('crop').hidden = mode !== 'crop';
  el('midArrow').hidden = mode !== 'arrow';
  el('midText').hidden = mode !== 'text';
  el('textLabel').hidden = mode !== 'text';
  hint.textContent = !loaded ? '' : mode === 'crop' ? 'Drag on the photo to choose the part to keep, then press Apply crop.'
    : mode === 'arrow' ? 'Drag on the photo from the arrow’s tail to its point.' : 'Type your text, then click on the photo where it should go.';
}
function defaultSel() { const w = base.width, h = base.height; sel = { x: Math.round(w * 0.1), y: Math.round(h * 0.1), w: Math.round(w * 0.8), h: Math.round(h * 0.8) }; }
function render() {
  if (view.width !== base.width || view.height !== base.height) { view.width = base.width; view.height = base.height; }
  vctx.clearRect(0, 0, view.width, view.height);
  vctx.drawImage(base, 0, 0);
  const lw = Math.max(2, base.width * 0.004);
  if (!loaded) return;
  if (mode === 'crop' && sel) {
    vctx.fillStyle = 'rgba(0,0,0,0.5)';
    vctx.fillRect(0, 0, view.width, sel.y);
    vctx.fillRect(0, sel.y + sel.h, view.width, view.height - sel.y - sel.h);
    vctx.fillRect(0, sel.y, sel.x, sel.h);
    vctx.fillRect(sel.x + sel.w, sel.y, view.width - sel.x - sel.w, sel.h);
    vctx.strokeStyle = '#fff'; vctx.lineWidth = lw; vctx.setLineDash([lw * 4, lw * 3]);
    vctx.strokeRect(sel.x, sel.y, sel.w, sel.h); vctx.setLineDash([]);
  }
  if (mode === 'arrow' && drag) drawArrow(vctx, drag.x0, drag.y0, drag.x1, drag.y1);
}
function drawArrow(ctx, x0, y0, x1, y1) {
  const lw = Math.max(3, base.width * parseFloat(el('size').value) * 0.2);
  const head = lw * 4, ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.strokeStyle = ctx.fillStyle = el('color').value;
  ctx.lineWidth = lw; ctx.lineCap = 'round';
  const bx = x1 - Math.cos(ang) * head * 0.8, by = y1 - Math.sin(ang) * head * 0.8;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(bx, by); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - head * Math.cos(ang - 0.45), y1 - head * Math.sin(ang - 0.45));
  ctx.lineTo(x1 - head * Math.cos(ang + 0.45), y1 - head * Math.sin(ang + 0.45));
  ctx.closePath(); ctx.fill();
}
function drawText(x, y) {
  const t = el('text').value.trim();
  if (!t) { say('Type some text first.', true); el('text').focus(); return false; }
  const ctx = base.getContext('2d');
  const px = Math.max(14, Math.round(base.width * parseFloat(el('size').value)));
  ctx.font = '600 ' + px + 'px "Segoe UI", Arial, sans-serif';
  ctx.textBaseline = 'middle'; ctx.textAlign = 'center';
  const col = el('color').value;
  ctx.lineWidth = Math.max(2, px * 0.12); ctx.lineJoin = 'round';
  ctx.strokeStyle = (col === '#ffffff' || col === '#f4c20d') ? 'rgba(0,0,0,0.6)' : 'rgba(255,255,255,0.7)';
  ctx.strokeText(t, x, y); ctx.fillStyle = col; ctx.fillText(t, x, y);
  return true;
}
function pushHistory() {
  const c = document.createElement('canvas'); c.width = base.width; c.height = base.height;
  c.getContext('2d').drawImage(base, 0, 0); undoStack.push(c);
  if (undoStack.length > 15) undoStack.shift();
}
function resizeBase(w, h) { base.width = w; base.height = h; }
function pos(ev) {
  const r = view.getBoundingClientRect();
  const x = (ev.clientX - r.left) * view.width / r.width, y = (ev.clientY - r.top) * view.height / r.height;
  return { x: Math.max(0, Math.min(view.width, x)), y: Math.max(0, Math.min(view.height, y)) };
}
view.addEventListener('pointerdown', (ev) => {
  if (!loaded) return;
  const p = pos(ev);
  if (mode === 'text') {
    pushHistory();
    if (drawText(p.x, p.y)) { say('Text added.'); } else { undoStack.pop(); }
    refreshButtons(); render(); return;
  }
  view.setPointerCapture(ev.pointerId);
  drag = { x0: p.x, y0: p.y, x1: p.x, y1: p.y };
});
view.addEventListener('pointermove', (ev) => {
  if (!drag) return;
  const p = pos(ev); drag.x1 = p.x; drag.y1 = p.y;
  if (mode === 'crop') sel = { x: Math.round(Math.min(drag.x0, p.x)), y: Math.round(Math.min(drag.y0, p.y)), w: Math.round(Math.abs(p.x - drag.x0)), h: Math.round(Math.abs(p.y - drag.y0)) };
  render();
});
view.addEventListener('pointerup', () => {
  if (!drag) return;
  const d = drag; drag = null;
  if (mode === 'arrow') {
    if (Math.hypot(d.x1 - d.x0, d.y1 - d.y0) < 10) { say('Drag a little further to make an arrow.', true); render(); return; }
    pushHistory(); drawArrow(base.getContext('2d'), d.x0, d.y0, d.x1, d.y1); say('Arrow added.');
  } else if (mode === 'crop') {
    say(sel && sel.w > 1 ? 'Crop area: ' + sel.w + ' × ' + sel.h + ' pixels. Press Apply crop to keep it.' : 'Drag a larger area to crop.');
  }
  refreshButtons(); render();
});
for (const r of document.querySelectorAll('input[name=mode]')) {
  r.addEventListener('change', () => { mode = r.value; if (loaded && mode === 'crop' && !sel) defaultSel(); refreshButtons(); render(); });
}
el('open').addEventListener('click', async () => {
  try {
    const f = await tessera.pickFile();
    if (!f) { say('No photo was chosen.'); return; }
    const img = new Image();
    img.src = await tessera.assetUrl(f.id);
    await img.decode();
    resizeBase(img.naturalWidth, img.naturalHeight);
    base.getContext('2d').drawImage(img, 0, 0);
    fileName = (f.name || 'photo').replace(/\.[^.]+$/, '') + '-edited';
    loaded = true; undoStack = []; defaultSel();
    say('Photo opened: ' + base.width + ' × ' + base.height + ' pixels.');
    refreshButtons(); render();
  } catch (e) { say('The photo could not be opened: ' + (e && e.message ? e.message : 'unknown problem'), true); }
});
el('crop').addEventListener('click', () => {
  if (!sel || sel.w < 2 || sel.h < 2) { say('Drag on the photo to choose a crop area first.', true); return; }
  pushHistory();
  const c = document.createElement('canvas'); c.width = sel.w; c.height = sel.h;
  c.getContext('2d').drawImage(base, sel.x, sel.y, sel.w, sel.h, 0, 0, sel.w, sel.h);
  resizeBase(sel.w, sel.h); base.getContext('2d').drawImage(c, 0, 0);
  defaultSel(); say('Cropped to ' + base.width + ' × ' + base.height + ' pixels.');
  refreshButtons(); render();
});
el('rotate').addEventListener('click', () => {
  pushHistory();
  const c = document.createElement('canvas'); c.width = base.height; c.height = base.width;
  const x = c.getContext('2d'); x.translate(c.width, 0); x.rotate(Math.PI / 2); x.drawImage(base, 0, 0);
  resizeBase(c.width, c.height); base.getContext('2d').drawImage(c, 0, 0);
  defaultSel(); say('Photo rotated.'); refreshButtons(); render();
});
el('midArrow').addEventListener('click', () => {
  pushHistory();
  drawArrow(base.getContext('2d'), base.width * 0.3, base.height * 0.7, base.width * 0.5, base.height * 0.5);
  say('Arrow added in the middle.'); refreshButtons(); render();
});
el('midText').addEventListener('click', () => {
  pushHistory();
  if (drawText(base.width / 2, base.height / 2)) say('Text added in the middle.'); else undoStack.pop();
  refreshButtons(); render();
});
el('undo').addEventListener('click', () => {
  const c = undoStack.pop(); if (!c) return;
  resizeBase(c.width, c.height); base.getContext('2d').drawImage(c, 0, 0);
  defaultSel(); say('Last change undone.'); refreshButtons(); render();
});
el('save').addEventListener('click', async () => {
  try {
    const ok = await tessera.saveFile({ name: fileName, type: 'image/png', bytesBase64: base.toDataURL('image/png').split(',')[1] });
    say(ok ? 'Photo saved.' : 'Not saved: the save was cancelled.', false);
  } catch (e) { say('The photo could not be saved: ' + (e && e.message ? e.message : 'unknown problem'), true); }
});
refreshButtons(); render();

